function generalTimer(t){endDates[t],startDates[t];const o=(endDates[t]-Date.now())/1e3;var n=Math.floor(o/24/60/60),e=Math.floor(o-86400*n),l=Math.floor(e/3600),a=Math.floor(e-3600*l),r=Math.floor(a/60),s=o%60;function d(t){const o=Math.floor(t);return o<10?"0"+o:o}let c=parseInt(d(n));c>0?$("#countdown-days-"+t).html(c+"<small>d</small>"):$("#countdown-days-"+t),$("#countdown-hours-"+t).html(d(l)),$("#countdown-mins-"+t).html(d(r)),$("#countdown-secs-"+t).html(d(s)),o<=0&&(clearInterval(countdownTimers[t]),$("#countdown-days-"+t).html("--"),$("#countdown-hours-"+t).html("--"),$("#countdown-mins-"+t).html("--"),$("#countdown-secs-"+t).html("--"))}var countdownTimers={};for(lotIdIndex in startDates)countdownTimers[lotIdIndex]=setInterval("generalTimer("+lotIdIndex+")",1e3);